<template>
	<view class="user-page">
		<view class="nav-bar" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="back-btn" @click="goBack">
				<text class="back-arrow"></text>
			</view>
			<text class="nav-title">个人主页</text>
			<view class="nav-placeholder" />
		</view>

		<scroll-view class="user-scroll" scroll-y enhanced :show-scrollbar="false" :style="{ paddingTop: headerHeight + 'px' }">
			<view class="profile-section">
				<view class="avatar-wrap">
					<image class="avatar" :src="profile.avatar" mode="aspectFill" />
					<view class="avatar-mark"></view>
				</view>
				<view class="profile-main">
					<view class="name-row">
						<VipName class="name" :name="profile.name" :is-member="profile.isMember" />
						<view class="match-pill">
							<text>同频指数</text>
							<text>{{ profile.match }}%</text>
						</view>
					</view>
					<view class="meta-row">
						<image class="gender-icon" :src="getGenderIcon(profile.gender)" mode="aspectFit" />
						<text>{{ profile.age }}岁</text>
						<text>·</text>
						<text>{{ profile.city }}</text>
						<text>·</text>
						<text>{{ profile.role }}</text>
					</view>
					<view class="intro-line">
						<text class="intro-line-label">个人介绍</text>
						<text class="intro-line-text">{{ displayedIntro }}</text>
					</view>
					<view class="verify-row">
						<view class="verify-chip">真人认证</view>
						<view class="verify-chip active">活跃中</view>
					</view>
				</view>
				<view
					v-if="!isSelfProfile"
					class="profile-more-action"
					aria-label="更多操作"
					@click="showActionSheet"
				>•••</view>
			</view>

			<view class="stats-card">
				<view class="stats-item">
					<text class="stats-value">{{ userStats.dynamicCount }}</text>
					<text class="stats-label">动态</text>
				</view>
				<view class="stats-sep"></view>
				<view class="stats-item">
					<text class="stats-value">{{ userStats.followingCount }}</text>
					<text class="stats-label">关注</text>
				</view>
				<view class="stats-sep"></view>
				<view class="stats-item">
					<text class="stats-value">{{ userStats.followerCount }}</text>
					<text class="stats-label">粉丝</text>
				</view>
				<view class="stats-sep"></view>
				<view class="stats-item">
					<text class="stats-value">{{ profile.charmValue || 0 }}</text>
					<text class="stats-label">魅力值</text>
				</view>
			</view>

			<view v-if="!isSelfProfile && litGifts.length" class="panel gift-panel">
				<view class="panel-head">
					<text class="panel-title">TA 的礼物</text>
					<text class="gift-count">已点亮 {{ litGifts.length }}</text>
				</view>
				<scroll-view class="gift-shelf-scroll" scroll-x enhanced :show-scrollbar="false">
					<view class="gift-shelf">
						<view
							v-for="(gift, index) in litGifts"
							:key="gift.id"
							class="profile-gift-item"
							@click="previewGift(index)"
						>
							<view class="profile-gift-image-wrap">
								<image class="profile-gift-image" :src="gift.staticImageUrl" mode="aspectFit" lazy-load />
								<text v-if="gift.receivedCount > 1" class="gift-received-count">×{{ gift.receivedCount }}</text>
							</view>
							<text class="profile-gift-name">{{ gift.name }}</text>
						</view>
					</view>
				</scroll-view>
			</view>

			<view class="panel album-panel">
				<view class="panel-head">
					<text class="panel-title">TA 的相册</text>
					<text v-if="albumTotal" class="album-count">{{ albumTotal }} 张</text>
				</view>
				<view v-if="albumItems.length" class="profile-album-row">
					<view
						v-for="(item, index) in albumItems"
						:key="item.key || item.url"
						class="profile-album-item"
						@click="previewAlbum(index)"
					>
						<image
							class="profile-album-image"
							:src="item.thumbnailUrl || item.url"
							mode="aspectFill"
							lazy-load
						/>
					</view>
				</view>
				<view v-else-if="!loading" class="empty-album">
					<text>TA 还没有公开照片。</text>
				</view>
			</view>

			<view class="panel">
				<view class="panel-head">
					<text class="panel-title">TA 的动态</text>
				</view>
				<view class="post-list">
					<view
						v-for="item in moments"
						:key="item.id"
						class="post-card"
						@click="goDetail(item.id)"
					>
						<view class="post-head">
							<image class="post-avatar" :src="profile.avatar" mode="aspectFill" />
							<view class="post-user-meta">
								<view class="post-name-row">
									<VipName class="post-nickname" :name="profile.name" :is-member="profile.isMember" />
									<view class="post-user-pill" :class="profile.gender === '男' ? 'male' : 'female'">
										<image class="post-gender-icon" :src="getGenderIcon(profile.gender)" mode="aspectFit" />
										<text v-if="profile.age">{{ profile.age }}</text>
									</view>
								</view>
								<text class="post-time-line">{{ item.time }} · {{ profile.city }}</text>
							</view>
						</view>

						<text class="post-text">{{ item.text }}</text>

						<view v-if="item.images.length" class="image-grid">
							<image
								v-for="(url, index) in item.images.slice(0, 3)"
								:key="url + index"
								class="post-image"
								:src="url"
								mode="aspectFill"
							/>
						</view>

						<view v-if="item.place" class="place-chip">
							<text class="pin-icon"></text>
							<text>{{ item.place }}</text>
						</view>

						<view class="post-footer">
							<view class="action active">
								<text class="heart-icon">♥</text>
								<text>{{ item.likes }}</text>
							</view>
							<view class="action">
								<image class="comment-icon" src="/static/tab/message.png" mode="aspectFit" />
								<text>{{ item.comments }}</text>
							</view>
							<view class="action" :class="{ 'favorite-active': item.favorited }" @click.stop="toggleFavorite(item)">
								<text class="star-icon">{{ item.favorited ? '★' : '☆' }}</text>
								<text>{{ item.favorites }}</text>
							</view>
						</view>
					</view>
					<view v-if="!loading && moments.length === 0" class="empty-moments">
						<text>TA 还没有公开动态。</text>
					</view>
				</view>
			</view>

			<view class="bottom-safe" :class="{ compact: isSelfProfile }"></view>
		</scroll-view>

		<view v-if="!isSelfProfile" class="bottom-actions">
			<view class="message-btn" @click="goWrite">发消息</view>
			<view class="follow-btn" :class="{ followed, disabled: followSubmitting || !profile.followable }" @click="toggleFollow">
				{{ followSubmitting ? '处理中' : (followed ? '已关注' : '关注') }}
			</view>
		</view>

		<view v-if="reportVisible" class="user-report-mask" @click="closeReportDialog">
			<view class="user-report-dialog" @click.stop>
				<view class="user-report-head">
					<text class="user-report-title">举报该用户</text>
					<text class="user-report-close" @click="closeReportDialog">关闭</text>
				</view>
				<text class="user-report-label">选择举报类型</text>
				<view class="user-report-options">
					<view
						v-for="item in reportOptions"
						:key="item.value"
						class="user-report-option"
						:class="{ active: reportReason === item.value }"
						@click="reportReason = item.value"
					>
						<view class="user-report-radio"><text /></view>
						<text>{{ item.label }}</text>
					</view>
				</view>
				<text class="user-report-label note-label">填写举报说明</text>
				<textarea
					v-model="reportNote"
					class="user-report-textarea"
					maxlength="200"
					placeholder="请描述具体情况，至少填写 5 个字"
					placeholder-class="user-report-placeholder"
				/>
				<view class="user-report-foot">
					<text>{{ reportNote.length }} / 200</text>
					<view
						class="user-report-submit"
						:class="{ disabled: !canSubmitUserReport }"
						@click="submitUserReport"
					>{{ reportSubmitting ? '提交中...' : '提交举报' }}</view>
				</view>
			</view>
		</view>
	</view>
</template>

<script>
import { DEFAULT_AVATAR_URL } from '../../config';
import { followUser, unfollowUser } from '../../api/follow';
import { toggleThoughtFavorite } from '../../api/thought';
import { blockUser, fetchUserProfile, reportUser } from '../../api/user';
import { showRequestError } from '../../utils/feedback';
import * as profileGuard from '../../utils/profileGuard';
import VipName from '../../components/VipName.vue';

const INTRO_DISPLAY_LIMIT = 40;

export default {
	components: { VipName },
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 96,
			loading: false,
			entryChecking: false,
			entryAllowed: false,
			loadError: '',
			followed: false,
			followSubmitting: false,
			blockSubmitting: false,
			reportVisible: false,
			reportReason: '',
			reportNote: '',
			reportSubmitting: false,
			reportOptions: [
				{ label: '骚扰或辱骂', value: 'harassment' },
				{ label: '诈骗或诱导', value: 'fraud' },
				{ label: '色情低俗', value: 'pornography' },
				{ label: '垃圾广告', value: 'spam' },
				{ label: '冒充他人', value: 'impersonation' },
				{ label: '其他问题', value: 'other' }
			],
			profile: {
				id: '',
				name: '同频旅人',
				avatar: DEFAULT_AVATAR_URL,
				gender: '保密',
				age: 0,
				city: '未知',
				role: '时光旅人',
				match: 86,
				intro: '正在加载资料...',
				signature: '正在加载资料...',
				quote: '正在加载资料...',
				followable: true,
				stats: {
					capsuleCount: 0,
					resonanceCount: 0,
					followingCount: 0,
					followerCount: 0
				}
			},
			moments: [],
			albumItems: [],
			albumTotal: 0,
			litGifts: []
		};
	},
	computed: {
		userStats() {
			const stats = this.profile.stats || {};
			return {
				dynamicCount: Number(stats.capsuleCount || 0),
				followingCount: Number(stats.followingCount || 0),
				followerCount: Number(stats.followerCount || 0)
			};
		},
		isSelfProfile() {
			return this.profile.followable === false;
		},
		canSubmitUserReport() {
			return Boolean(this.reportReason) && this.reportNote.trim().length >= 5 && !this.reportSubmitting;
		},
		displayedIntro() {
			const intro = String(this.profile.intro || this.profile.signature || '还没写个人介绍。').trim();
			if (intro.length <= INTRO_DISPLAY_LIMIT) return intro;
			return `${intro.slice(0, INTRO_DISPLAY_LIMIT)}...`;
		}
	},
	onLoad(options = {}) {
		this.profile.id = options.id || '';
		this.setHeaderHeight();
		this.ensureEntryThenLoad();
	},
	onShow() {
		if (!this.profile.id || this.entryAllowed) return;
		this.ensureEntryThenLoad();
	},
	methods: {
		setHeaderHeight() {
			try {
				const info = uni.getSystemInfoSync();
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.statusBarHeight = info.statusBarHeight || 44;
				this.headerHeight = this.statusBarHeight + Math.round(92 * rpxToPx);
			} catch (error) {
				this.headerHeight = 96;
			}
		},
		getGenderIcon(gender) {
			return gender === '男' ? '/static/img/nan-icon.png' : '/static/img/nv-icon.png';
		},
		async ensureEntryThenLoad() {
			if (this.entryChecking) return;
			if (!this.profile.id) {
				uni.showToast({ title: '缺少用户信息', icon: 'none' });
				return;
			}
			this.entryChecking = true;
			try {
				const allowed = await profileGuard.ensureProfileCompleted({ actionText: '查看主页' });
				this.entryAllowed = Boolean(allowed);
				if (allowed) this.loadProfile();
			} finally {
				this.entryChecking = false;
			}
		},
		async loadProfile() {
			if (!this.profile.id) {
				uni.showToast({ title: '缺少用户信息', icon: 'none' });
				return;
			}

			this.loading = true;
			this.loadError = '';
			try {
				const result = await fetchUserProfile(this.profile.id);
				const profile = result && result.profile ? result.profile : {};
				const moments = Array.isArray(result && result.moments) ? result.moments : [];
				const album = result && result.album ? result.album : {};
				const gifts = result && result.gifts ? result.gifts : {};
				this.profile = this.normalizeProfile(profile);
				this.followed = Boolean(profile.followed);
				this.moments = moments.map(this.normalizeMoment);
				this.albumItems = (Array.isArray(album.items) ? album.items : [])
					.filter((item) => item && item.url)
					.slice(0, 4);
				this.albumTotal = Number(album.total || this.albumItems.length);
				this.litGifts = (Array.isArray(gifts.items) ? gifts.items : [])
					.filter((gift) => gift && gift.id && gift.staticImageUrl)
					.map((gift) => ({
						...gift,
						receivedCount: Number(gift.receivedCount || 0)
					}));
			} catch (error) {
				this.loadError = error && error.message ? error.message : '主页暂不可见';
				this.profile = {
					...this.profile,
					name: '主页暂不可见',
					avatar: DEFAULT_AVATAR_URL,
					gender: '保密',
					age: 0,
					city: '未知',
					role: '时光旅人',
					match: 0,
					intro: this.loadError,
					signature: this.loadError,
					quote: this.loadError
				};
				this.moments = [];
				this.albumItems = [];
				this.albumTotal = 0;
				this.litGifts = [];
				showRequestError(error, '个人主页加载失败');
			} finally {
				this.loading = false;
			}
		},
		normalizeProfile(profile = {}) {
			return {
				id: profile.id || this.profile.id || '',
				userId: profile.userId || null,
				name: profile.name || profile.nickname || '同频旅人',
				isMember: Boolean(profile.isMember),
				charmValue: Number(profile.charmValue || 0),
				avatar: profile.avatar || profile.avatarUrl || DEFAULT_AVATAR_URL,
				gender: profile.gender || '保密',
				age: Number(profile.age || 0),
				city: profile.city || '未知',
				role: profile.role || '时光旅人',
				match: Number(profile.match || 86),
				intro: profile.intro || profile.signature || '还没写个人介绍。',
				signature: profile.signature || profile.intro || '还没写个人介绍。',
				quote: profile.quote || profile.intro || '有些念头不必被解释，只要被温柔地看见。',
				isVirtual: Boolean(profile.isVirtual),
				followable: profile.followable !== false,
				stats: {
					capsuleCount: Number((profile.stats && profile.stats.capsuleCount) || profile.capsuleCount || 0),
					resonanceCount: Number((profile.stats && profile.stats.resonanceCount) || profile.resonanceCount || 0),
					followingCount: Number((profile.stats && profile.stats.followingCount) || profile.followingCount || 0),
					followerCount: Number((profile.stats && profile.stats.followerCount) || profile.followerCount || 0)
				}
			};
		},
		normalizeMoment(moment = {}) {
			const tags = Array.isArray(moment.tags) ? moment.tags : [];
			return {
				id: moment.id || `${Date.now()}-${Math.random()}`,
				images: this.getImageUrls(moment.images || (moment.image ? [moment.image] : [])),
				text: moment.text || '留下了一条新的动态。',
				time: moment.time || '',
				likes: Number(moment.resonanceCount || moment.likes || 0),
				comments: Number(moment.commentCount || moment.comments || 0),
				favorites: Number(moment.favoriteCount || moment.favorites || 0),
				favorited: Boolean(moment.isFavorited || moment.favorited),
				place: moment.topicTitle || tags[0] || ''
			};
		},
		getImageUrls(images = []) {
			return (Array.isArray(images) ? images : [])
				.map((item) => (typeof item === 'string' ? item : item && item.url))
				.filter(Boolean);
		},
		previewAlbum(index) {
			const urls = this.albumItems.map((item) => item.url).filter(Boolean);
			if (!urls.length) return;
			uni.previewImage({ current: urls[index], urls });
		},
		previewGift(index) {
			const urls = this.litGifts.map((gift) => gift.staticImageUrl).filter(Boolean);
			if (!urls.length) return;
			uni.previewImage({ current: urls[index], urls });
		},
		async toggleFavorite(item) {
			if (!item || !item.id) return;
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '收藏' }))) return;
			const previousFavorited = Boolean(item.favorited);
			const previousFavorites = Number(item.favorites || 0);
			const nextFavorited = !previousFavorited;
			item.favorited = nextFavorited;
			item.favorites = Math.max(0, previousFavorites + (nextFavorited ? 1 : -1));

			try {
				const response = await toggleThoughtFavorite(item.id);
				if (response && typeof response === 'object') {
					const nextFavorites = response.favoriteCount !== undefined ? response.favoriteCount : response.favorites;
					item.favorited = Boolean(response.isFavorited || response.favorited);
					item.favorites = nextFavorites !== undefined ? nextFavorites : item.favorites;
				}
				uni.showToast({ title: item.favorited ? '已收藏' : '已取消收藏', icon: 'none' });
			} catch (error) {
				item.favorited = previousFavorited;
				item.favorites = previousFavorites;
				showRequestError(error, nextFavorited ? '收藏失败' : '取消收藏失败');
			}
		},
		async toggleFollow() {
			if (!this.profile.followable || this.followSubmitting) return;
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '关注' }))) return;
			const nextFollowed = !this.followed;
			const previousFollowed = this.followed;
			const previousStats = { ...(this.profile.stats || {}) };
			this.followed = nextFollowed;
			this.profile = {
				...this.profile,
				stats: {
					...previousStats,
					followerCount: Math.max(0, Number(previousStats.followerCount || 0) + (nextFollowed ? 1 : -1))
				}
			};
			this.followSubmitting = true;
			try {
				const result = nextFollowed
					? await followUser(this.profile.id)
					: await unfollowUser(this.profile.id);
				this.followed = Boolean(result && result.followed);
				this.profile = {
					...this.profile,
					stats: {
						...(this.profile.stats || {}),
						followingCount: Number((result && result.followingCount) || this.profile.stats.followingCount || 0),
						followerCount: Number((result && result.followerCount) || this.profile.stats.followerCount || 0)
					}
				};
			} catch (error) {
				this.followed = previousFollowed;
				this.profile = {
					...this.profile,
					stats: previousStats
				};
				showRequestError(error, nextFollowed ? '关注失败' : '取关失败');
			} finally {
				this.followSubmitting = false;
			}
		},
		async goWrite() {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '私信' }))) return;
			const suffix = this.profile.id ? `?to=${this.profile.id}` : '';
			uni.navigateTo({ url: `/pages/chat/index${suffix}` });
		},
		async goDetail(id) {
			if (!id) return;
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看详情' }))) return;
			uni.navigateTo({ url: `/pages/detail/index?id=${encodeURIComponent(id)}` });
		},
		showActionSheet() {
			uni.showActionSheet({
				itemList: ['拉黑', '举报'],
				itemColor: '#d4688a',
				success: ({ tapIndex }) => {
					if (tapIndex === 0) {
						this.confirmBlockUser();
						return;
					}
					setTimeout(() => this.openReportDialog(), 120);
				}
			});
		},
		async openReportDialog() {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '举报' }))) return;
			this.reportVisible = true;
		},
		closeReportDialog() {
			if (!this.reportSubmitting) this.reportVisible = false;
		},
		async submitUserReport() {
			if (!this.canSubmitUserReport) {
				uni.showToast({
					title: this.reportReason ? '请至少填写 5 个字' : '请选择举报类型',
					icon: 'none'
				});
				return;
			}
			this.reportSubmitting = true;
			try {
				await reportUser(this.profile.id, {
					reason: this.reportReason,
					note: this.reportNote.trim()
				});
				this.reportVisible = false;
				this.reportReason = '';
				this.reportNote = '';
				uni.showToast({ title: '举报已提交', icon: 'success' });
			} catch (error) {
				showRequestError(error, '举报提交失败');
			} finally {
				this.reportSubmitting = false;
			}
		},
		confirmBlockUser() {
			if (this.blockSubmitting || !this.profile.id || this.isSelfProfile) return;
			uni.showModal({
				title: '拉黑该用户？',
				content: '拉黑后双方不能私信、查看主页或互动帖子，已有关注关系也会解除。',
				confirmText: '确认拉黑',
				confirmColor: '#d84f75',
				success: ({ confirm }) => {
					if (confirm) this.submitBlockUser();
				}
			});
		},
		async submitBlockUser() {
			if (this.blockSubmitting) return;
			this.blockSubmitting = true;
			try {
				await blockUser(this.profile.id);
				uni.showToast({ title: '已加入黑名单', icon: 'none' });
				setTimeout(() => this.goBack(), 500);
			} catch (error) {
				showRequestError(error, '拉黑失败');
			} finally {
				this.blockSubmitting = false;
			}
		},
		goBack() {
			const pages = getCurrentPages();
			if (pages.length > 1) {
